<?php
if(PHP_SAPI!=='cli')exit;
require __DIR__.'/../../Api/Db_connection/db_connect.php';require __DIR__.'/../../Api/Helpers/agency_landing_content.php';
$conn->query('CREATE TEMPORARY TABLE systemsettings (SettingID INT AUTO_INCREMENT PRIMARY KEY,SettingKey VARCHAR(100),SettingValue TEXT,SettingType VARCHAR(30),Category VARCHAR(50),IsEditable INT,UpdatedBy INT) ENGINE=InnoDB');
function ok($v,$label){if(!$v)throw new Exception($label);echo "PASS $label\n";}
$values=agency_landing_validate(['company_name'=>'Test Agency','about'=>"We help applicants.\nLearn more here.",'office_hours'=>'Mon-Fri, 9 AM-5 PM','website'=>'https://example.com','mission'=>'','facebook'=>'']);$conn->begin_transaction();agency_landing_save($conn,$values,12);$conn->commit();$read=agency_landing_read($conn);ok($read['about']===$values['about'] && $read['website']===$values['website'],'new settings persist and public allowlist reads values');agency_landing_save($conn,['about'=>'Updated description'],12);ok(agency_landing_read($conn)['about']==='Updated description','existing details can be edited');$conn->begin_transaction();agency_landing_save($conn,['about'=>'Rollback test'],12);$conn->rollback();ok(agency_landing_read($conn)['about']==='Updated description','transaction rollback preserves previous content');foreach([['website'=>'javascript:alert(1)'],['facebook'=>'http://example.com'],['about'=>str_repeat('x',3001)],['mission'=>['invalid']]] as $invalid){$blocked=false;try{agency_landing_validate($invalid);}catch(DomainException $e){$blocked=true;}ok($blocked,'unsafe URL or invalid/overlong text rejected');}ok(!array_key_exists('secret',agency_landing_validate(['secret'=>'hidden'])),'unknown settings excluded');
